mapper.delete:
DELETE FROM sms_send_request
WHERE idempotency_key = #{idempotencyKey}
  AND idempotent_expire_time <= #{now}
  AND status IN (2, 3, 4)

DELETE FROM sms_send_request
WHERE idempotent_expire_time <= #{now}
  AND status IN (2, 3, 4)
LIMIT #{limit}

mapper.update:
UPDATE sms_send_request
SET status = 1, update_time = #{updateTime}
WHERE id = #{id} AND status = 0

UPDATE sms_send_request
SET status = 0, update_time = #{updateTime}
WHERE id = #{id} AND status = 1

UPDATE sms_send_request
SET status = 2, failure_reason = NULL, update_time = #{updateTime}
WHERE id = #{id} AND status = 1

UPDATE sms_send_request
SET status = 3, failure_reason = #{failureReason}, update_time = #{updateTime}
WHERE id = #{id} AND status IN (0, 1)

UPDATE sms_send_request
SET status = 4, failure_reason = #{failureReason}, update_time = #{updateTime}
WHERE id = #{id} AND status IN (0, 1)
